import { Name } from "@ndn/packet";
import { batch, consume, pipeline, transform } from "streaming-iterables";
export async function copy(src, arg2, arg3, arg4) {
    const [prefix, dst, opts = {}] = arg2 instanceof Name ? [arg2, arg3, arg4] : [undefined, arg2, arg3];
    const { batch: batchSize = 64, parallel = 1, } = opts;
    const insertOpts = { ...opts };
    delete insertOpts.batch;
    delete insertOpts.parallel;
    let n = 0;
    await pipeline(() => src.listData(prefix), batch(batchSize), transform(parallel, async (pkts) => {
        await dst.insert(insertOpts, ...pkts);
        n += pkts.length;
    }), consume);
    return n;
}
